#!/usr/bin/env bash
# Configure the patched kernel tree by copying the authoritative full .config
# in, running olddefconfig, and aborting if olddefconfig changed anything.
#
# Architecture (the "PKGBUILD method"):
#   - configs/config.${DISTRO}-${RELEASE}-${ARCH} is the SINGLE source of
#     truth. It is a complete kconfig snapshot, generated by a previous
#     successful build's olddefconfig pass against this exact kernel tree.
#   - At each build, we cp it in, run olddefconfig, and diff. A non-empty
#     diff means upstream introduced new symbols or changed defaults; the
#     operator inspects, decides, and commits the updated authoritative.
#   - This replaces the older "Debian stock seed + hardening overlay" model
#     (configs/hardened-overlay.config + configs/{distro}-{release}-{arch}
#     .config merged via scripts/kconfig/merge_config.sh against a freshly
#     fetched Debian source seed). That was the class of finding the audit
#     caught: silent symbol drops as the seed (built for a different kernel
#     version) and the patched tree drifted apart. With the authoritative
#     config as input, the only thing that can drift is the kernel itself,
#     and the diff makes that visible at configure time -- fail-fast in ~2
#     minutes, not after a 30+ minute compile.
#
# Required env:
#   WORKDIR
#   KERNEL_VERSION
#   DISTRO RELEASE ARCH
#
# Optional env:
#   MODULE_SIG_KEY_PATH   override CONFIG_MODULE_SIG_KEY to a CI-runtime
#                         path so the kernel build signs modules with the
#                         project's key. Applied AFTER the drift check so
#                         the CI-ephemeral path never pollutes the diff.

set -euo pipefail
umask 022

: "${WORKDIR:?WORKDIR required}"
: "${KERNEL_VERSION:?KERNEL_VERSION required}"
: "${DISTRO:?DISTRO required}"
: "${RELEASE:?RELEASE required}"
: "${ARCH:?ARCH required}"

repo_root="$(cd "$(dirname "$0")/.." && pwd)"
src_dir="$WORKDIR/linux-${KERNEL_VERSION}"
authoritative="$repo_root/configs/config.${DISTRO}-${RELEASE}-${ARCH}"

[[ -d $src_dir ]]       || { echo "kernel source tree not found at $src_dir" >&2; exit 1; }
[[ -f $authoritative ]] || { echo "missing authoritative config: $authoritative" >&2; exit 1; }

cd "$src_dir"

# Step 1: copy the authoritative config in.
cp "$authoritative" .config

# Translate Debian/dpkg arch name (amd64, arm64) to the kernel build's
# arch name (x86_64, arm64). The kernel has arch/x86/ and arch/arm64/;
# there is no arch/amd64/. The matrix and authoritative-config filenames
# stay on the Debian convention; this translation is local to make.
case "$ARCH" in
    amd64) kernel_arch=x86_64 ;;
    arm64) kernel_arch=arm64 ;;
    *) echo "unsupported ARCH: $ARCH" >&2; exit 2 ;;
esac

# Step 2: olddefconfig fills in any newly-introduced defaults (or accepts
# upstream-flipped defaults for symbols we don't pin explicitly).
echo "running olddefconfig"
make ARCH="$kernel_arch" olddefconfig

# Step 3: drift check. The authoritative was generated by a prior build's
# olddefconfig against this exact tree, so re-running olddefconfig on an
# unchanged tree must be a no-op. Any diff means one of:
#   - The kernel version bumped and introduced new symbols / flipped defaults.
#   - The hardened patch revision changed.
#   - The toolchain (gcc/binutils, recorded in CONFIG_CC_VERSION_TEXT) changed.
# Aborting forces explicit review of every upstream change at configure time.
echo "running drift check (authoritative vs post-olddefconfig)"
diff_out="$WORKDIR/config.diff"
rm -f "$diff_out"
if ! diff -u "$authoritative" .config > "$diff_out"; then
    {
        echo
        echo "DRIFT detected: olddefconfig altered the authoritative config."
        echo "Diff:"
        cat "$diff_out"
        cat <<EOF

Resolve by EITHER:
  - Inspecting the diff above, deciding the new symbols/defaults are
    acceptable, and committing the updated config (copy this build's
    final .config over configs/config.${DISTRO}-${RELEASE}-${ARCH} after
    stripping the MODULE_SIG_KEY runtime path -- see
    tools/promote-config.sh).
  - Pinning the affected symbols explicitly in the authoritative to their
    desired value (= to override an unwanted new default).

This guard fires every kernel-version or hardened-patch-revision bump;
that is intentional -- each bump warrants explicit review of what
upstream changed.
EOF
    } >&2
    exit 2
fi
rm -f "$diff_out"
echo "drift check: OK (authoritative == post-olddefconfig)"

# Step 4: post-diff mutations. Intentionally after the drift check so the
# CI-runtime signing-key path never pollutes the diff.
#
# If the workflow materialized a project signing key + cert PEM and passed
# MODULE_SIG_KEY_PATH, override CONFIG_MODULE_SIG_KEY to point at it. The
# kernel build then signs every module with our project key during compile
# and embeds the matching cert in the kernel's .builtin_trusted_keys.
# Without this, the build auto-generates an ephemeral key, embeds the
# ephemeral cert, and our post-build module signatures fail to verify at
# boot ("Loading of module with unavailable key is rejected").
if [[ -n "${MODULE_SIG_KEY_PATH:-}" ]]; then
    [[ -f $MODULE_SIG_KEY_PATH ]] || {
        echo "MODULE_SIG_KEY_PATH set but file missing: $MODULE_SIG_KEY_PATH" >&2
        exit 1
    }
    echo "pinning CONFIG_MODULE_SIG_KEY=$MODULE_SIG_KEY_PATH"
    sed -i '/^CONFIG_MODULE_SIG_KEY=/d; /^# CONFIG_MODULE_SIG_KEY/d' .config
    printf 'CONFIG_MODULE_SIG_KEY="%s"\n' "$MODULE_SIG_KEY_PATH" >> .config
fi

echo "configure-kernel.sh: OK"
